import 'ahlulbayt_dua_model.dart';

/// مستودع أدعية أهل البيت (عليهم السلام) والصحيفة السجادية.
class AhlulbaytDuasRepository {
  AhlulbaytDuasRepository._();

  /// النسخة المفردة (Singleton).
  static final AhlulbaytDuasRepository instance = AhlulbaytDuasRepository._();

  /// قائمة الأدعية المأثورة الموثقة.
  static const List<AhlulbaytDua> defaultDuas = [
    // 1. دعاء كميل بن زياد
    AhlulbaytDua(
      id: 'dua_kumayl',
      title: 'دعاء كميل بن زياد',
      attributedTo: 'أمير المؤمنين علي بن أبي طالب (عليه السلام)',
      category: 'ليلة الجمعة والتوبة',
      summary:
          'علّمه الإمام علي بن أبي طالب لكميل بن زياد، ويُقرأ في ليلة الجمعة ومنتصف شعبان طلباً للمغفرة وكشف الكربات وسعة الرزق.',
      paragraphs: [
        'اللَّهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ، وَبِقُوَّتِكَ الَّتِي قَهَرْتَ بِهَا كُلَّ شَيْءٍ، وَخَضَعَ لَهَا كُلُّ شَيْءٍ، وَذَلَّ لَهَا كُلُّ شَيْءٍ، وَبِجَبَرُوتِكَ الَّتِي غَلَبْتَ بِهَا كُلَّ شَيْءٍ، وَبِعِزَّتِكَ الَّتِي لا يَقُومُ لَهَا شَيْءٌ.',
        'وَبِعَظَمَتِكَ الَّتِي مَلَأَتْ كُلَّ شَيْءٍ، وَبِسُلْطَانِكَ الَّذِي عَلَا كُلَّ شَيْءٍ، وَبِوَجْهِكَ الْبَاقِي بَعْدَ فَنَاءِ كُلِّ شَيْءٍ، وَبِأَسْمَائِكَ الَّتِي مَلَأَتْ أَرْكَانَ كُلِّ شَيْءٍ، وَبِعِلْمِكَ الَّذِي أَحَاطَ بِكُلِّ شَيْءٍ، وَبِنُورِ وَجْهِكَ الَّذِي أَضَاءَ لَهُ كُلُّ شَيْءٍ، يَا نُورُ يَا قُدُّوسُ، يَا أَوَّلَ الْأَوَّلِينَ وَيَا آخِرَ الْآخِرِينَ.',
        'اللَّهُمَّ اغْفِرْ لِيَ الذُّنُوبَ الَّتِي تَهْتِكُ الْعِصَمَ، اللَّهُمَّ اغْفِرْ لِيَ الذُّنُوبَ الَّتِي تُنْزِلُ النِّقَمَ، اللَّهُمَّ اغْفِرْ لِيَ الذُّنُوبَ الَّتِي تُغَيِّرُ النِّعَمَ، اللَّهُمَّ اغْفِرْ لِيَ الذُّنُوبَ الَّتِي تَحْبِسُ الدُّعَاءَ، اللَّهُمَّ اغْفِرْ لِيَ الذُّنُوبَ الَّتِي تَقْطَعُ الرَّجَاءَ، اللَّهُمَّ اغْفِرْ لِيَ الذُّنُوبَ الَّتِي تُنْزِلُ الْبَلاءَ.',
        'اللَّهُمَّ اغْفِرْ لِي كُلَّ ذَنْبٍ أَذْنَبْتُهُ، وَكُلَّ خَطِيئَةٍ أَخْطَأْتُهَا، اللَّهُمَّ إِنِّي أَتَقَرَّبُ إِلَيْكَ بِذِكْرِكَ، وَأَسْتَشْفِعُ بِكَ إِلَى نَفْسِكَ، وَأَسْأَلُكَ بِجُودِكَ أَنْ تُدْنِيَنِي مِنْ قُرْبِكَ، وَأَنْ تُوزِعَنِي شُكْرَكَ، وَأَنْ تُلْهِمَنِي ذِكْرَكَ.',
        'اللَّهُمَّ إِنِّي أَسْأَلُكَ سُؤَالَ خَاضِعٍ مُتَذَلِّلٍ خَاشِعٍ، أَنْ تُسَامِحَنِي وَتَرْحَمَنِي، وَتَجْعَلَنِي بِقِسْمِكَ رَاضِياً قَانِعاً، وَفِي جَمِيعِ الْأَحْوَالِ مُتَوَاضِعاً.',
        'إِلَهِي وَرَبِّي مَنْ لِي غَيْرُكَ أَسْأَلُهُ كَشْفَ ضُرِّي وَالنَّظَرَ فِي أَمْرِي. إِلَهِي وَمَوْلايَ أَجْرَيْتَ عَلَيَّ حُكْماً اتَّبَعْتُ فِيهِ هَوَى نَفْسِي، وَلَمْ أَحْتَرِسْ فِيهِ مِنْ تَزْيِينِ عَدُوِّي، فَغَرَّنِي بِمَا أَهْوَى وَأَسْعَدَهُ عَلَى ذَلِكَ الْقَضَاءُ.',
        'يَا رَبِّ ارْحَمْ ضَعْفَ بَدَنِي، وَرِقَّةَ جِلْدِي، وَدِقَّةَ عَظْمِي، يَا مَنْ بَدَأَ خَلْقِي وَذِكْرِي وَتَرْبِيَتِي وَبِرِّي وَتَغْذِيَتِي، هَبْنِي لِابْتِدَاءِ كَرَمِكَ وَسَالِفِ بِرِّكَ بِي.',
        'يَا سَيِّدِي وَمَوْلايَ، فَأَسْأَلُكَ بِعِزَّتِكَ أَنْ لا يَحْجُبَ عَنْكَ دُعَائِي سُوءُ عَمَلِي وَفِعَالِي، وَلا تَفْضَحْنِي بِخَفِيِّ مَا اطَّلَعْتَ عَلَيْهِ مِنْ سِرِّي، وَلا تُعَاجِلْنِي بِالْعُقُوبَةِ عَلَى مَا عَمِلْتُهُ فِي خَلَوَاتِي مِنْ سُوءِ فِعْلِي وَإِسَاءَتِي، وَدَوَامِ تَفْرِيطِي وَجَهَالَتِي، وَكَثْرَةِ شَهَوَاتِي وَغَفْلَتِي.',
        'اللَّهُمَّ وَمَنْ أَرَادَنِي بِسُوءٍ فَأَرِدْهُ، وَمَنْ كَادَنِي فَكِدْهُ، وَاجْعَلْنِي مِنْ أَحْسَنِ عَبِيدِكَ نَصِيباً عِنْدَكَ، وَأَقْرَبِهِمْ مَنْزِلَةً مِنْكَ، وَأَخَصِّهِمْ زُلْفَةً لَدَيْكَ، فَإِنَّهُ لا يُنَالُ ذَلِكَ إِلا بِفَضْلِكَ، وَجُدْ لِي بِجُودِكَ، وَاعْطِفْ عَلَيَّ بِمَجْدِكَ، وَاحْفَظْنِي بِرَحْمَتِكَ، وَاجْعَلْ لِسَانِي بِذِكْرِكَ لَهِجاً، وَقَلْبِي بِحُبِّكَ مُتَيَّماً.',
        'يَا سَرِيعَ الرِّضَا، اغْفِرْ لِمَنْ لا يَمْلِكُ إِلا الدُّعَاءَ، فَإِنَّكَ فَعَّالٌ لِمَا تَشَاءُ، يَا مَنِ اسْمُهُ دَوَاءٌ، وَذِكْرُهُ شِفَاءٌ، وَطَاعَتُهُ غِنىً، ارْحَمْ مَنْ رَأْسُ مَالِهِ الرَّجَاءُ، وَسِلاحُهُ الْبُكَاءُ، يَا سَابِغَ النِّعَمِ، يَا دَافِعَ النِّقَمِ، يَا نُورَ الْمُسْتَوْحِشِينَ فِي الظُّلَمِ، يَا عَالِماً لا يُعَلَّمُ، صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَافْعَلْ بِي مَا أَنْتَ أَهْلُهُ.',
      ],
    ),

    // 2. دعاء مكارم الأخلاق
    AhlulbaytDua(
      id: 'dua_makarim_akhlaq',
      title: 'دعاء مكارم الأخلاق',
      attributedTo: 'الإمام علي بن الحسين زين العابدين (عليه السلام)',
      category: 'الصحيفة السجادية والتربية',
      summary:
          'من أشهر أدعية الإمام زين العابدين في الصحيفة السجادية؛ يسأل فيه العبد ربه خصال الطهارة، وحسن الخلق، والتحلي بالفضائل، وتزكية النفس.',
      paragraphs: [
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَبَلِّغْ بِإِيمَانِي أَكْمَلَ الإِيمَانِ، وَاجْعَلْ يَقِينِي أَفْضَلَ الْيَقِينِ، وَانْتَهِ بِنِيَّتِي إِلَى أَحْسَنِ النِّيَّاتِ، وَبِعَمَلِي إِلَى أَحْسَنِ الأَعْمَالِ.',
        'اللَّهُمَّ وَفِّرْ بِلُطْفِكَ نِيَّتِي، وَصَحِّحْ بِمَا عِنْدَكَ يَقِينِي، وَاسْتَصْلِحْ بِقُدْرَتِكَ مَا فَسَدَ مِنِّي.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاكْفِنِي مَا يَشْغَلُنِي الاِهْتِمَامُ بِهِ، وَاسْتَعْمِلْنِي بِمَا تَسْأَلُنِي غَداً عَنْهُ، وَاسْتَفْرِغْ أَيَّامِي فِيمَا خَلَقْتَنِي لَهُ، وَأَغْنِنِي وَأَوْسِعْ عَلَيَّ فِي رِزْقِكَ، وَلا تَفْتِنِّي بِالنَّظَرِ، وَأَعِزَّنِي وَلا تَبْتَلِيَنِّي بِالْكِبْرِ، وَعَبِّدْنِي لَكَ وَلا تُفْسِدْ عِبَادَتِي بِالْعُجْبِ، وَأَجْرِ لِلنَّاسِ عَلَى يَدِيَ الْخَيْرَ وَلا تَمْحَقْهُ بِالْمَنِّ، وَهَبْ لِي مَعَالِيَ الأَخْلاقِ، وَاعْصِمْنِي مِنَ الْفَخْرِ.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلا تَرْفَعْنِي فِي النَّاسِ دَرَجَةً إِلا حَطَطْتَنِي عِنْدَ نَفْسِي مِثْلَهَا، وَلا تُحْدِثْ لِي عِزّاً ظَاهِراً إِلا أَحْدَثْتَ لِي ذِلَّةً بَاطِنَةً عِنْدَ نَفْسِي بِقَدَرِهَا.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَمَتِّعْنِي بِهُدًى صَالِحٍ لا أَسْتَبْدِلُ بِهِ، وَطَرِيقَةِ حَقٍّ لا أَزِيغُ عَنْهَا، وَنِيَّةِ رُشْدٍ لا أَشُكُّ فِيهَا، وَعَمِّرْنِي مَا كَانَ عُمُرِي بِذْلَةً فِي طَاعَتِكَ، فَإِذَا كَانَ عُمُرِي مَرْتَعاً لِلشَّيْطَانِ فَاقْبِضْنِي إِلَيْكَ قَبْلَ أَنْ يَسْبِقَ مَقْتُكَ إِلَيَّ، أَوْ يَسْتَحْكِمَ غَضَبُكَ عَلَيَّ.',
        'اللَّهُمَّ لا تَدَعْ خَصْلَةً تُعَابُ مِنِّي إِلا أَصْلَحْتَهَا، وَلا عَائِبَةً أُوَنَّبُ بِهَا إِلا حَسَّنْتَهَا، وَلا أُكْرُومَةً فِيَّ نَاقِصَةً إِلا أَتْمَمْتَهَا.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَسَدِّدْنِي لأَنْ أُعَارِضَ مَنْ غَشَّنِي بِالنُّصْحِ، وَأَجْزِيَ مَنْ هَجَرَنِي بِالْبِرِّ، وَأُثِيبَ مَنْ حَرَمَنِي بِالْبَذْلِ، وَأُكَافِئَ مَنْ قَطَعَنِي بِالصِّلَةِ، وَأُخَالِفَ مَنِ اغْتَابَنِي إِلَى حُسْنِ الذِّكْرِ، وَأَنْ أَشْكُرَ الْحَسَنَةَ، وَأُغْضِيَ عَنِ السَّيِّئَةِ.',
      ],
    ),

    // 3. دعاء أهل الثغور
    AhlulbaytDua(
      id: 'dua_ahl_thughoor',
      title: 'دعاء أهل الثغور (حماة الحدود والبقاع)',
      attributedTo: 'الإمام علي بن الحسين زين العابدين (عليه السلام)',
      category: 'الصحيفة السجادية والجهاد',
      summary:
          'دعاء جليل من أدعية الصحيفة السجادية، يدعو فيه لحماية المسلمين وثغورهم، ونصرة حماة الوطن والمرابطين على الحدود ودفع كيد المعتدين.',
      paragraphs: [
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَحَصِّنْ ثُغُورَ الْمُسْلِمِينَ بِعِزَّتِكَ، وَأَيِّدْ حُمَاتَهَا بِقُوَّتِكَ، وَأَسْبِغْ عَطَايَاهُمْ مِنْ جِدَتِكَ.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَكَثِّرْ عِدَّتَهُمْ، وَاشْحَذْ أَسْلِحَتَهُمْ، وَاحْرُسْ حَوْزَتَهُمْ، وَامْنَعْ حَوْمَتَهُمْ، وَأَلِّفْ جَمْعَهُمْ، وَدَبِّرْ أَمْرَهُمْ، وَوَاتِرْ بَيْنَ مِيَرِهِمْ، وَتَوَحَّدْ بِكِفَايَةِ مَؤَنِهِمْ، وَاعْضُدْهُمْ بِالنَّصْرِ، وَأَعِنْهُمْ بِالصَّبْرِ، وَالْطُفْ لَهُمْ فِي الْمَكْرِ.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَعَرِّفْهُمْ مَا يَجْهَلُونَ، وَعَلِّمْهُمْ مَا لا يَعْلَمُونَ، وَبَصِّرْهُمْ مَا لا يُبْصِرُونَ.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَنْسِهِمْ عِنْدَ لِقَائِهِمُ الْعَدُوَّ ذِكْرَ دُنْيَاهُمُ الْخَدَّاعَةِ الْغَرُورِ، وَامْحُ عَنْ قُلُوبِهِمْ خَطَرَاتِ الْمَالِ الْفَتُونِ، وَاجْعَلِ الْجَنَّةَ نُصْبَ أَعْيُنِهِمْ، وَلَوِّحْ مِنْهَا لأَبْصَارِهِمْ مَا أَعْدَدْتَ فِيهَا مِنْ مَسَاكِنِ الْخُلْدِ وَمَنَازِلِ الْكَرَامَةِ.',
        'اللَّهُمَّ وَأَيُّمَا مُسْلِمٍ خَلَفَ غَازِياً أَوْ مُرَابِطاً فِي دَارِهِ، أَوْ تَعَهَّدَ خَالِفِيهِ فِي غَيْبَتِهِ، أَوْ أَعَانَهُ بِطَائِفَةٍ مِنْ مَالِهِ، أَوْ أَمَدَّهُ بِعِتَادٍ، أَوْ حَثَّهُ عَلَى جِهَادٍ، أَوْ أَتْبَعَهُ فِي وَجْهِهِ دَعْوَةً، أَوْ رَعَى لَهُ مِنْ وَرَائِهِ حُرْمَةً، فَآجِرْ لَهُ مِثْلَ أَجْرِهِ وَزْناً بِوَزْنٍ وَمِثْلاً بِمِثْلٍ.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَعِزَّ بِذَلِكَ الإِسْلامَ، وَاخْذُلْ بِهِ الشِّرْكَ وَالْكُفْرَ وَالْعُدْوَانَ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.',
      ],
    ),

    // 4. دعاء التوسل
    AhlulbaytDua(
      id: 'dua_tawassul',
      title: 'دعاء التوسل',
      attributedTo: 'مروي عن الأئمة الأطهار (عليهم السلام)',
      category: 'التوسل وقضاء الحوائج',
      summary:
          'دعاء معروف وشريف يتوسل فيه الداعي إلى الله تعالى بالنبي المصطفى وآله الأطهار واحداً بعد واحد لقضاء الحوائج وغفران الذنوب.',
      paragraphs: [
        'اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِنَبِيِّكَ نَبِيِّ الرَّحْمَةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ، يَا أَبَا الْقَاسِمِ، يَا رَسُولَ اللَّهِ، يَا إِمَامَ الرَّحْمَةِ، يَا سَيِّدَنَا وَمَوْلانَا، إِنَّا تَوَجَّهْنَا وَاسْتَشْفَعْنَا وَتَوَسَّلْنَا بِكَ إِلَى اللَّهِ، وَقَدَّمْنَاكَ بَيْنَ يَدَيْ حَاجَاتِنَا، يَا وَجِيهاً عِنْدَ اللَّهِ اشْفَعْ لَنَا عِنْدَ اللَّهِ.',
        'يَا أَبَا الْحَسَنِ، يَا أَمِيرَ الْمُؤْمِنِينَ، يَا عَلِيَّ بْنَ أَبِي طَالِبٍ، يَا حُجَّةَ اللَّهِ عَلَى خَلْقِهِ، يَا سَيِّدَنَا وَمَوْلانَا، إِنَّا تَوَجَّهْنَا وَاسْتَشْفَعْنَا وَتَوَسَّلْنَا بِكَ إِلَى اللَّهِ، وَقَدَّمْنَاكَ بَيْنَ يَدَيْ حَاجَاتِنَا، يَا وَجِيهاً عِنْدَ اللَّهِ اشْفَعْ لَنَا عِنْدَ اللَّهِ.',
        'يَا فَاطِمَةَ الزَّهْرَاءَ، يَا بِنْتَ مُحَمَّدٍ، يَا قُرَّةَ عَيْنِ الرَّسُولِ، يَا سَيِّدَتَنَا وَمَوْلاتَنَا، إِنَّا تَوَجَّهْنَا وَاسْتَشْفَعْنَا وَتَوَسَّلْنَا بِكِ إِلَى اللَّهِ، وَقَدَّمْنَاكِ بَيْنَ يَدَيْ حَاجَاتِنَا، يَا وَجِيهَةً عِنْدَ اللَّهِ اشْفَعِي لَنَا عِنْدَ اللَّهِ.',
        'يَا أَبَا مُحَمَّدٍ، يَا حَسَنَ بْنَ عَلِيٍّ، أَيُّهَا الْمُجْتَبَى، يَا بْنَ رَسُولِ اللَّهِ... يَا وَجِيهاً عِنْدَ اللَّهِ اشْفَعْ لَنَا عِنْدَ اللَّهِ.',
        'يَا أَبَا عَبْدِ اللَّهِ، يَا حُسَيْنَ بْنَ عَلِيٍّ، أَيُّهَا الشَّهِيدُ، يَا بْنَ رَسُولِ اللَّهِ... يَا وَجِيهاً عِنْدَ اللَّهِ اشْفَعْ لَنَا عِنْدَ اللَّهِ.',
        'يَا أَبَا الْحَسَنِ، يَا عَلِيَّ بْنَ الْحُسَيْنِ، يَا زَيْنَ الْعَابِدِينَ... يَا أَبَا جَعْفَرٍ، يَا مُحَمَّدَ بْنَ عَلِيٍّ، أَيُّهَا الْبَاقِرُ... يَا أَبَا عَبْدِ اللَّهِ، يَا جَعْفَرَ بْنَ مُحَمَّدٍ، أَيُّهَا الصَّادِقُ... يَا أَبَا الْحَسَنِ، يَا مُوسَى بْنَ جَعْفَرٍ، أَيُّهَا الْكَاظِمُ... يَا أَبَا الْحَسَنِ، يَا عَلِيَّ بْنَ مُوسَى، أَيُّهَا الرِّضَا... يَا أَبَا جَعْفَرٍ، يَا مُحَمَّدَ بْنَ عَلِيٍّ، أَيُّهَا التَّقِيُّ الْجَوَادُ... يَا أَبَا الْحَسَنِ، يَا عَلِيَّ بْنَ مُحَمَّدٍ، أَيُّهَا الْهَادِي النَّقِيُّ... يَا أَبَا مُحَمَّدٍ، يَا حَسَنَ بْنَ عَلِيٍّ، أَيُّهَا الزَّكِيُّ الْعَسْكَرِيُّ... يَا وَصِيَّ الْحَسَنِ، وَالْخَلَفَ الْحُجَّةَ، أَيُّهَا الْقَائِمُ الْمُنْتَظَرُ الْمَهْدِيُّ، يَا بْنَ رَسُولِ اللَّهِ، يَا حُجَّةَ اللَّهِ عَلَى خَلْقِهِ، يَا سَيِّدَنَا وَمَوْلانَا، إِنَّا تَوَجَّهْنَا وَاسْتَشْفَعْنَا وَتَوَسَّلْنَا بِكَ إِلَى اللَّهِ، وَقَدَّمْنَاكَ بَيْنَ يَدَيْ حَاجَاتِنَا، يَا وَجِيهاً عِنْدَ اللَّهِ اشْفَعْ لَنَا عِنْدَ اللَّهِ.',
        'يَا سَادَتِي وَمَوَالِيَّ، إِنِّي تَوَجَّهْتُ بِكُمْ أَئِمَّتِي وَعُدَّتِي لِيَوْمِ فَقْرِي وَحَاجَتِي إِلَى اللَّهِ، وَتَوَسَّلْتُ بِكُمْ إِلَى اللَّهِ، وَاسْتَشْفَعْتُ بِكُمْ إِلَى اللَّهِ، فَاشْفَعُوا لِي عِنْدَ اللَّهِ، وَاسْتَنْقِذُونِي مِنْ ذُنُوبِي عِنْدَ اللَّهِ، فَإِنَّكُمْ وَسِيلَتِي إِلَى اللَّهِ، وَبِحُبِّكُمْ وَبِقُرْبِكُمْ أَرْجُو نَجَاةً مِنَ اللَّهِ، فَكُونُوا عِنْدَ اللَّهِ رَجَائِي، يَا سَادَتِي يَا أَوْلِيَاءَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِمْ أَجْمَعِينَ.',
      ],
    ),

    // 5. دعاء الندبة
    AhlulbaytDua(
      id: 'dua_nudba',
      title: 'دعاء الندبة',
      attributedTo: 'مروي عن الإمام جعفر الصادق (عليه السلام)',
      category: 'صباح الجمعة والأعياد',
      summary:
          'يُدعَى به في صباح الجمعة والأعياد الأربعة؛ يتضمن التوسل وإظهار الحزن والشوق لغيبة الإمام المهدي (عجل الله فرجه) واستحضار تاريخ الأنبياء والأولياء.',
      paragraphs: [
        'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ نَبِيِّهِ وَآلِهِ وَسَلَّمَ تَسْلِيماً. اللَّهُمَّ لَكَ الْحَمْدُ عَلَى مَا جَرَى بِهِ قَضَاؤُكَ فِي أَوْلِيَائِكَ الَّذِينَ اسْتَخْلَصْتَهُمْ لِنَفْسِكَ وَدِينِكَ، إِذِ اخْتَرْتَ لَهُمْ جَزِيلَ مَا عِنْدَكَ مِنَ النَّعِيمِ الْمُقِيمِ الَّذِي لا زَوَالَ لَهُ وَلا اضْمِحْلالَ، بَعْدَ أَنْ شَرَطْتَ عَلَيْهِمُ الزُّهْدَ فِي دَرَجَاتِ هَذِهِ الدُّنْيَا الدَّنِيَّةِ وَزُخْرُفِهَا وَزِبْرِجِهَا، فَشَرَطُوا لَكَ ذَلِكَ، وَعَلِمْتَ مِنْهُمُ الْوَفَاءَ بِهِ، فَقَبِلْتَهُمْ وَقَرَّبْتَهُمْ، وَقَدَّمْتَ لَهُمُ الذِّكْرَ الْعَلِيَّ وَالثَّنَاءَ الْجَلِيَّ.',
        'فَبَعْضٌ أَسْكَنْتَهُ جَنَّتَكَ إِلَى أَنْ أَخْرَجْتَهُ مِنْهَا، وَبَعْضٌ حَمَلْتَهُ فِي فُلْكِكَ وَنَجَّيْتَهُ وَمَنْ آمَنَ مَعَهُ مِنَ الْهَلَكَةِ بِرَحْمَتِكَ، وَبَعْضٌ اتَّخَذْتَهُ لِنَفْسِكَ خَلِيلاً، وَبَعْضٌ كَلَّمْتَهُ مِنْ شَجَرَةٍ تَكْلِيماً، وَبَعْضٌ آتَيْتَهُ الْبَيِّنَاتِ وَأَيَّدْتَهُ بِرُوحِ الْقُدُسِ.',
        'إِلَى أَنِ انْتَهَيْتَ بِالأَمْرِ إِلَى حَبِيبِكَ وَنَجِيبِكَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ، فَكَانَ كَمَا انْتَجَبْتَهُ سَيِّدَ مَنْ خَلَقْتَهُ، وَصَفْوَةَ مَنِ اصْطَفَيْتَهُ... ثُمَّ جَعَلْتَ أَجْرَ مُحَمَّدٍ صَلَوَاتُكَ عَلَيْهِ وَآلِهِ مَوَدَّتَهُمْ فِي كِتَابِكَ فَقُلْتَ: ﴿قُلْ لا أَسْأَلُكُمْ عَلَيْهِ أَجْراً إِلا الْمَوَدَّةَ فِي الْقُرْبَى﴾.',
        'فَلَمَّا انْقَضَتْ أَيَّامُهُ أَقَامَ وَلِيَّهُ عَلِيَّ بْنَ أَبِي طَالِبٍ صَلَوَاتُكَ عَلَيْهِمَا وَآلِهِمَا هَادِياً... أَيْنَ الْحَسَنُ أَيْنَ الْحُسَيْنُ؟ أَيْنَ أَبْنَاءُ الْحُسَيْنِ؟ صَالِحٌ بَعْدَ صَالِحٍ، وَصَادِقٌ بَعْدَ صَادِقٍ، أَيْنَ السَّبِيلُ بَعْدَ السَّبِيلِ؟ أَيْنَ الْخِيَرَةُ بَعْدَ الْخِيَرَةِ؟ أَيْنَ الشُّمُوسُ الطَّالِعَةُ؟ أَيْنَ الأَقْمَارُ الْمُنِيرَةُ؟ أَيْنَ الأَنْجُمُ الزَّاهِرَةُ؟',
        'أَيْنَ بَقِيَّةُ اللَّهِ الَّتِي لا تَخْلُو مِنَ الْعِتْرَةِ الْهَادِيَةِ؟ أَيْنَ الْمُعَدُّ لِقَطْعِ دَابِرِ الظَّلَمَةِ؟ أَيْنَ الْمُنْتَظَرُ لإِقَامَةِ الأَمْتِ وَالْعِوَجِ؟ أَيْنَ الْمُرْتَجَى لإِزَالَةِ الْجَوْرِ وَالْعُدْوَانِ؟ أَيْنَ الْمُدَّخَرُ لِتَجْدِيدِ الْفَرَائِضِ وَالسُّنَنِ؟',
        'عَزِيزٌ عَلَيَّ أَنْ أَرَى الْخَلْقَ وَلا تُرى، وَلا أَسْمَعَ لَكَ حَسِيساً وَلا نَجْوَى، عَزِيزٌ عَلَيَّ أَنْ تُحِيطَ بِكَ دُونِيَ الْبَلْوَى، وَلا يَنَالَكَ مِنِّي ضَجِيجٌ وَلا شَكْوَى، بِنَفْسِي أَنْتَ مِنْ مُغَيَّبٍ لَمْ يَخْلُ مِنَّا، بِنَفْسِي أَنْتَ مِنْ نَازِحٍ مَا نَزَحَ عَنَّا، بِنَفْسِي أَنْتَ أُمْنِيَّةُ شَائِقٍ يَتَمَنَّى.',
      ],
    ),

    // 6. دعاء الإمام الحسين (يوم عرفة)
    AhlulbaytDua(
      id: 'dua_arafah_hussein',
      title: 'دعاء الإمام الحسين (يوم عرفة)',
      attributedTo: 'سيد الشهداء الإمام الحسين بن علي (عليهما السلام)',
      category: 'يوم عرفة والتوحيد',
      summary:
          'دعاء طويل وعميق ألقاه الإمام الحسين في صعيد عرفات؛ يفيض بمعرفة الله وتوحيده، والثناء عليه بحمده وشكره على نعمه الظاهرة والباطنة.',
      paragraphs: [
        'الْحَمْدُ لِلَّهِ الَّذِي لَيْسَ لِقَضَائِهِ دَافِعٌ، وَلا لِعَطَائِهِ مَانِعٌ، وَلا كَصُنْعِهِ صُنْعُ صَانِعٍ، وَهُوَ الْجَوَادُ الْوَاسِعُ، فَطَرَ أَجْنَاسَ الْبَدَائِعِ، وَأَتْقَنَ بِحِكْمَتِهِ الصَّنَائِعَ، لا تَخْفَى عَلَيْهِ الطَّلائِعُ، وَلا تَضِيعُ عِنْدَهُ الْوَدَائِعُ، جَازِي كُلِّ صَانِعٍ، وَرَائِشُ كُلِّ قَانِعٍ، وَرَاحِمُ كُلِّ ضَارِعٍ، وَمُنْزِلُ الْمَنَافِعِ وَالْكِتَابِ الْجَامِعِ، بِالنُّورِ السَّاطِعِ، وَهُوَ لِلدَّعَوَاتِ سَامِعٌ، وَلِلْكُرُبَاتِ دَافِعٌ، وَلِلدَّرَجَاتِ رَافِعٌ.',
        'اللَّهُمَّ إِنِّي أَرْغَبُ إِلَيْكَ، وَأَشْهَدُ بِالرُّبُوبِيَّةِ لَكَ، مُقِرّاً بِأَنَّكَ رَبِّي، وَأَنَّ إِلَيْكَ مَرَدِّي، ابْتَدَأْتَنِي بِنِعْمَتِكَ قَبْلَ أَنْ أَكُونَ شَيْئاً مَذْكُوراً، وَخَلَقْتَنِي مِنَ التُّرَابِ، ثُمَّ أَسْكَنْتَنِي الأَصْلابَ، آمِناً لِرَيْبِ الْمَنُونِ، وَاخْتِلافِ الدُّهُورِ وَالسِّنِينَ.',
        'ثُمَّ إِذْ أَوْجَبْتَ عَلَيَّ حُجَّتَكَ بِأَنْ أَلْهَمْتَنِي مَعْرِفَتَكَ، وَآنَسْتَنِي بِعَجَائِبِ حِكْمَتِكَ، وَأَيْقَظْتَنِي لِمَا ذَرَأْتَ فِي سَمَائِكَ وَأَرْضِكَ مِنْ بَدَائِعِ خَلْقِكَ، وَنَبَّهْتَنِي لِشُكْرِكَ وَذِكْرِكَ، وَأَوْجَبْتَ عَلَيَّ طَاعَتَكَ وَعِبَادَتَكَ، وَفَهَّمْتَنِي مَا جَاءَتْ بِهِ رُسُلُكَ، وَيَسَّرْتَ لِي تَقَبُّلَ مَرْضَاتِكَ، وَمَنَنْتَ عَلَيَّ فِي جَمِيعِ ذَلِكَ بِعَوْنِكَ وَلُطْفِكَ.',
        'إِلَهِي أَنَا الْفَقِيرُ فِي غِنَايَ، فَكَيْفَ لا أَكُونُ فَقِيراً فِي فَقْرِي؟ إِلَهِي أَنَا الْجَاهِلُ فِي عِلْمِي، فَكَيْفَ لا أَكُونُ جَهُولاً فِي جَهْلِي؟ إِلَهِي إِنَّ اخْتِلافَ تَدْبِيرِكَ وَسُرْعَةَ طَوَاءِ مَقَادِيرِكَ مَنَعَا عِبَادَكَ الْعَارِفِينَ بِكَ عَنِ السُّكُونِ إِلَى عَطَاءٍ، وَالْيَأْسِ مِنْكَ فِي بَلاءٍ.',
        'إِلَهِي كَيْفَ يُسْتَدَلُّ عَلَيْكَ بِمَا هُوَ فِي وُجُودِهِ مُفْتَقِرٌ إِلَيْكَ؟ أَيَكُونُ لِغَيْرِكَ مِنَ الظُّهُورِ مَا لَيْسَ لَكَ حَتَّى يَكُونَ هُوَ الْمُظْهِرَ لَكَ؟ مَتَى غِبْتَ حَتَّى تَحْتَاجَ إِلَى دَلِيلٍ يَدُلُّ عَلَيْكَ؟ وَمَتَى بَعُدْتَ حَتَّى تَكُونَ الآثَارُ هِيَ الَّتِي تُوصِلُ إِلَيْكَ؟ عَمِيَتْ عَيْنٌ لا تَرَاكَ عَلَيْهَا رَقِيباً، وَخَسِرَتْ صَفْقَةُ عَبْدٍ لَمْ تَجْعَلْ لَهُ مِنْ حُبِّكَ نَصِيباً.',
        'مَاذَا وَجَدَ مَنْ فَقَدَكَ؟ وَمَا الَّذِي فَقَدَ مَنْ وَجَدَكَ؟ لَقَدْ خَابَ مَنْ رَضِيَ دُونَكَ بَدَلاً، وَلَقَدْ خَسِرَ مَنْ بَغَى عَنْكَ مُتَحَوَّلاً. يَا مَنْ أَذَاقَ أَحِبَّاءَهُ حَلاوَةَ الْمُؤَانَسَةِ فَقَامُوا بَيْنَ يَدَيْهِ مَتَمَلِّقِينَ، وَيَا مَنْ أَلْبَسَ أَوْلِيَاءَهُ مَلابِسَ هَيْبَتِهِ فَقَامُوا بَيْنَ يَدَيْهِ مُسْتَغْفِرِينَ، أَنْتَ الذَّاكِرُ قَبْلَ الذَّاكِرِينَ، وَأَنْتَ الْبَادِي بِالإِحْسَانِ قَبْلَ تَوَجُّهِ الْعَابِدِينَ.',
      ],
    ),

    // 7. دعاء الجوشن الكبير
    AhlulbaytDua(
      id: 'dua_jawshan_kabir',
      title: 'دعاء الجوشن الكبير',
      attributedTo: 'مروي عن النبي ﷺ ورواه أهل البيت (عليهم السلام)',
      category: 'الأسماء الحسنى والأمان',
      summary:
          'منسوب للنبي (صلى الله عليه وآله) ورواه أهل البيت؛ يشتمل على ألف اسم وصفة لله تعالى في مائة فصل، ويُطلب به الأمان التام من البلايا والشرور.',
      paragraphs: [
        'بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nاللَّهُمَّ إِنِّي أَسْأَلُكَ بِاسْمِكَ: يَا اللَّهُ، يَا رَحْمَنُ، يَا رَحِيمُ، يَا كَرِيمُ، يَا مُقِيمُ، يَا عَظِيمُ، يَا قَدِيمُ، يَا عَلِيمُ، يَا حَلِيمُ، يَا حَكِيمُ،\nسُبْحَانَكَ يَا لا إِلَهَ إِلا أَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنَا مِنَ النَّارِ يَا رَبِّ.',
        'يَا سَيِّدَ السَّادَاتِ، يَا مُجِيبَ الدَّعَوَاتِ، يَا رَافِعَ الدَّرَجَاتِ، يَا وَلِيَّ الْحَسَنَاتِ، يَا غَافِرَ الْخَطِيئَاتِ، يَا مُعْطِيَ الْمَسْأَلاتِ، يَا قَابِلَ التَّوْبَاتِ، يَا سَامِعَ الأَصْوَاتِ، يَا عَالِمَ الْخَفِيَّاتِ، يَا دَافِعَ الْبَلِيَّاتِ،\nسُبْحَانَكَ يَا لا إِلَهَ إِلا أَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنَا مِنَ النَّارِ يَا رَبِّ.',
        'يَا خَيْرَ الْغَافِرِينَ، يَا خَيْرَ الْفَاتِحِينَ، يَا خَيْرَ النَّاصِرِينَ، يَا خَيْرَ الْحَاكِمِينَ، يَا خَيْرَ الرَّازِقِينَ، يَا خَيْرَ الْوَارِثِينَ، يَا خَيْرَ الْحَامِدِينَ، يَا خَيْرَ الذَّاكِرِينَ، يَا خَيْرَ الْمُنْزِلِينَ، يَا خَيْرَ الْمُحْسِنِينَ،\nسُبْحَانَكَ يَا لا إِلَهَ إِلا أَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنَا مِنَ النَّارِ يَا رَبِّ.',
        'يَا مَنْ لَهُ الْعِزَّةُ وَالْجَمَالُ، يَا مَنْ لَهُ الْقُدْرَةُ وَالْكَمَالُ، يَا مَنْ لَهُ الْمُلْكُ وَالْجَلالُ، يَا مَنْ هُوَ الْكَبِيرُ الْمُتَعَالِ، يَا مُنْشِئَ السَّحَابِ الثِّقَالِ، يَا مَنْ هُوَ شَدِيدُ الْمِحَالِ، يَا مَنْ هُوَ سَرِيعُ الْحِسَابِ، يَا مَنْ هُوَ شَدِيدُ الْعِقَابِ، يَا مَنْ عِنْدَهُ حُسْنُ الثَّوَابِ، يَا مَنْ عِنْدَهُ أُمُّ الْكِتَابِ،\nسُبْحَانَكَ يَا لا إِلَهَ إِلا أَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنَا مِنَ النَّارِ يَا رَبِّ.',
        'يَا عِمَادَ مَنْ لا عِمَادَ لَهُ، يَا سَنَدَ مَنْ لا سَنَدَ لَهُ، يَا ذُخْرَ مَنْ لا ذُخْرَ لَهُ، يَا حِرْزَ مَنْ لا حِرْزَ لَهُ، يَا غِيَاثَ مَنْ لا غِيَاثَ لَهُ، يَا فَخْرَ مَنْ لا فَخْرَ لَهُ، يَا عِزَّ مَنْ لا عِزَّ لَهُ، يَا مُعِينَ مَنْ لا مُعِينَ لَهُ، يَا أَنِيسَ مَنْ لا أَنِيسَ لَهُ، يَا أَمَانَ مَنْ لا أَمَانَ لَهُ،\nسُبْحَانَكَ يَا لا إِلَهَ إِلا أَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنَا مِنَ النَّارِ يَا رَبِّ.',
        'يَا كَافِيَ مَنِ اسْتَكْفَاهُ، يَا هَادِيَ مَنِ اسْتَهْدَاهُ، يَا كَالِئَ مَنِ اسْتَكْلاهُ، يَا رَاعِيَ مَنِ اسْتَرْعَاهُ، يَا شَافِيَ مَنِ اسْتَشْفَاهُ، يَا قَاضِيَ مَنِ اسْتَقْضَاهُ، يَا مُغْنِيَ مَنِ اسْتَغْنَاهُ، يَا مُوفِيَ مَنِ اسْتَوْفَاهُ، يَا مُقَوِّيَ مَنِ اسْتَقْوَاهُ، يَا وَلِيَّ مَنِ اسْتَوْلاهُ،\nسُبْحَانَكَ يَا لا إِلَهَ إِلا أَنْتَ، الْغَوْثَ الْغَوْثَ، خَلِّصْنَا مِنَ النَّارِ يَا رَبِّ.',
      ],
    ),

    // 8. دعاء الإمام الصادق لقضاء الحوائج
    AhlulbaytDua(
      id: 'dua_sadiq_hawaaj',
      title: 'دعاء الإمام الصادق لقضاء الحوائج والخشية',
      attributedTo: 'الإمام جعفر بن محمد الصادق (عليه السلام)',
      category: 'قضاء الحوائج واليقين',
      summary:
          'دعاء عظيم مروي عن الإمام الصادق؛ يسأل فيه العبد ربه دوام الخشية، وسعادة التقوى، والرضا بالقضاء، والغنى في النفس، والنصرة على الظالمين.',
      paragraphs: [
        'اللّهُمَّ اجْعَلْني أخْشاكَ كأني أراكَ، وَأسْعِدْني بِتَقْواكَ، وَلا تُشْقِني بِنَشْطي لِمَعاصيكَ، وَخِرْ لي في قَضائِكَ، وَبارِكْ لي في قَدَرِكَ، حَتّى لا أُحِبَّ تَعْجيلَ ما أخَّرْتَ، وَلا تَأْخيرَ ما عَجَّلْتَ.',
        'وَاجْعَلْ غِنايَ في نَفْسي، وَمَتِّعْني بِسَمْعي وَبَصَري، وَاجْعَلْهُما الوارِثَيْنِ مِنّي، وَانْصُرْني عَلى مَنْ ظَلَمَني، وَأَرِني فيهِ قُدْرَتَكَ يا رَبِّ، وَأَقِرَّ بِذلِكَ عَيْني.',
        'اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَاناً تُبَاشِرُ بِهِ قَلْبِي، وَيَقِيناً صَادِقاً حَتَّى أَعْلَمَ أَنَّهُ لا يُصِيبُنِي إِلا مَا كَتَبْتَ لِي، وَرَضِّنِي بِمَا قَسَمْتَ لِي يَا أَرْحَمَ الرَّاحِمِينَ.',
      ],
    ),

    // 9. دعاء السيدة فاطمة الزهراء (عليها السلام)
    AhlulbaytDua(
      id: 'dua_zahra_peace',
      title: 'دعاء السيدة فاطمة الزهراء (عليها السلام)',
      attributedTo: 'سيدة نساء العالمين فاطمة الزهراء (عليها السلام)',
      category: 'الاستغاثة وإصلاح الشأن',
      summary:
          'دعاء مبارك علّمه النبي لابنته الزهراء؛ فيه الاستغاثة برحمة الحي القيوم والتبرؤ من الحول والقوة وسؤال كفاية النفس وإصلاح الأمر كله.',
      paragraphs: [
        'يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ، فَأَغِثْنِي، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ أَبَداً، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ.',
        'اللَّهُمَّ إِنِّي أَسْأَلُكَ قُوَّةً فِي عِبَادَتِكَ، وَتَبَصُّراً فِي كِتَابِكَ، وَفَهْماً فِي حُكْمِكَ. اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَلا تَجْعَلِ الْقُرْآنَ بِنَا مَاحِلاً، وَالصِّرَاطَ زَائِلاً، وَمُحَمَّداً صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ عَنَّا مُوَلِّياً.',
      ],
    ),

    // 10. دعاء الفرج (إلهي عظم البلاء)
    AhlulbaytDua(
      id: 'dua_faraj',
      title: 'دعاء الفرج (إلهي عظم البلاء)',
      attributedTo: 'مروي عن الإمام المهدي صاحب الزمان (عجل الله فرجه)',
      category: 'الفرج وكشف الكروب',
      summary:
          'دعاء جليل يُقرأ لكشف الشدائد ورفع البلاء العظيم وتعجيل فرج الأمة بالنبي وآله الأطهار.',
      paragraphs: [
        'إِلَهِي عَظُمَ الْبَلاءُ، وَبَرِحَ الْخَفَاءُ، وَانْكَشَفَ الْغِطَاءُ، وَانْقَطَعَ الرَّجَاءُ، وَضَاقَتِ الأَرْضُ وَمُنِعَتِ السَّمَاءُ، وَأَنْتَ الْمُسْتَعَانُ وَإِلَيْكَ الْمُشْتَكَى، وَعَلَيْكَ الْمُعَوَّلُ فِي الشِّدَّةِ وَالرَّخَاءِ.',
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، أُولِي الأَمْرِ الَّذِينَ فَرَضْتَ عَلَيْنَا طَاعَتَهُمْ، وَعَرَّفْتَنَا بِذَلِكَ مَنْزِلَتَهُمْ، فَفَرِّجْ عَنَّا بِحَقِّهِمْ فَرَجاً عَاجِلاً قَرِيباً كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ.',
        'يَا مُحَمَّدُ يَا عَلِيُّ، يَا عَلِيُّ يَا مُحَمَّدُ، اكْفِيَانِي فَإِنَّكُمَا كَافِيَانِ، وَانْصُرَانِي فَإِنَّكُمَا نَاصِرَانِ، يَا مَوْلانَا يَا صَاحِبَ الزَّمَانِ، الْغَوْثَ الْغَوْثَ الْغَوْثَ، أَدْرِكْنِي أَدْرِكْنِي أَدْرِكْنِي، السَّاعَةَ السَّاعَةَ السَّاعَةَ، الْعَجَلَ الْعَجَلَ الْعَجَلَ، يَا أَرْحَمَ الرَّاحِمِينَ، بِحَقِّ مُحَمَّدٍ وَآلِهِ الطَّاهِرِينَ.',
      ],
    ),

    // 11. دعاء الصباح لأمير المؤمنين
    AhlulbaytDua(
      id: 'dua_sabah_ali',
      title: 'دعاء الصباح لأمير المؤمنين',
      attributedTo: 'أمير المؤمنين علي بن أبي طالب (عليه السلام)',
      category: 'الصباح والتوحيد البليغ',
      summary:
          'من أبلغ أدعية أمير المؤمنين في استهلال الصباح؛ فصاحة تامة وبيان إلهي في تمجيد الخالق والاعتصام بحبله.',
      paragraphs: [
        'اللَّهُمَّ يَا مَنْ دَلَعَ لِسَانَ الصَّبَاحِ بِنُطْقِ تَبَلُّجِهِ، وَسَرَّحَ قِطَعَ اللَّيْلِ الْمُظْلِمِ بِغَيَاهِبِ تَلَجْلُجِهِ، وَأَتْقَنَ صُنْعَ الْفَلَكِ الدَّوَّارِ فِي مَقَادِيرِ تَبَرُّجِهِ، وَشَعْشَعَ ضِيَاءَ الشَّمْسِ بِنُورِ تَأَجُّجِهِ، يَا مَنْ دَلَّ عَلَى ذَاتِهِ بِذَاتِهِ، وَتَنَزَّهَ عَنْ مُجَانَسَةِ مَخْلُوقَاتِهِ، وَجَلَّ عَنْ مُلاءَمَةِ كَيْفِيَّاتِهِ.',
        'يَا مَنْ قَرُبَ مِنْ خَطَرَاتِ الظُّنُونِ، وَبَعُدَ عَنْ لَحَظَاتِ الْعُيُونِ، وَعَلِمَ بِمَا كَانَ قَبْلَ أَنْ يَكُونَ، يَا مَنْ أَرْقَدَنِي فِي مِهَادِ أَمْنِهِ وَأَمَانِهِ، وَأَيْقَظَنِي إِلَى مَا مَنَحَنِي بِهِ مِنْ مِنَنِهِ وَإِحْسَانِهِ، وَكَفَّ أَكُفَّ السُّوءِ عَنِّي بِيَدِهِ وَسُلْطَانِهِ.',
        'صَلِّ اللَّهُمَّ عَلَى الدَّلِيلِ إِلَيْكَ فِي اللَّيْلِ الأَلْيَلِ، وَالْمَاسِكِ مِنْ أَسْبَابِكَ بِحَبْلِ الشَّرَفِ الأَطْوَلِ، وَالنَّاصِعِ الْحَسَبِ فِي ذِرْوَةِ الْكَاهِلِ الأَعْبَلِ، وَالثَّابِتِ الْغَدَرِ فِي زَحَالِيفِهِ فِي الزَّمَنِ الأَوَّلِ، وَعَلَى آلِهِ الأَخْيَارِ الْمُصْطَفَيْنَ الأَبْرَارِ، وَافْتَحِ اللَّهُمَّ لَنَا مَصَارِيعَ الصَّبَاحِ بِمَفَاتِيحِ الرَّحْمَةِ وَالْفَلاحِ.',
      ],
    ),

    // 12. دعاء العهد
    AhlulbaytDua(
      id: 'dua_ahd',
      title: 'دعاء العهد',
      attributedTo: 'مروي عن الإمام جعفر الصادق (عليه السلام)',
      category: 'تجديد العهد والصباح',
      summary:
          'مروي عن الإمام الصادق ويُستحب قراءته أربعين صباحاً لتجديد البيعة والارتباط الروحي بإمام العصر والزمان.',
      paragraphs: [
        'اللَّهُمَّ رَبَّ النُّورِ الْعَظِيمِ، وَرَبَّ الْكُرْسِيِّ الرَّفِيعِ، وَرَبَّ الْبَحْرِ الْمَسْجُورِ، وَمُنْزِلَ التَّوْرَاةِ وَالإِنْجِيلِ وَالزَّبُورِ، وَرَبَّ الظِّلِّ وَالْحَرُورِ، وَمُنْزِلَ الْقُرْآنِ الْعَظِيمِ، وَرَبَّ الْمَلائِكَةِ الْمُقَرَّبِينَ وَالأَنْبِيَاءِ وَالْمُرْسَلِينَ.',
        'اللَّهُمَّ إِنِّي أَسْأَلُكَ بِوَجْهِكَ الْكَرِيمِ، وَبِنُورِ وَجْهِكَ الْمُنِيرِ، وَمُلْكِكَ الْقَدِيمِ، يَا حَيُّ يَا قَيُّومُ، أَسْأَلُكَ بِاسْمِكَ الَّذِي أَشْرَقَتْ بِهِ السَّمَاوَاتُ وَالأَرَضُونَ، وَبِاسْمِكَ الَّذِي يَصْلَحُ بِهِ الأَوَّلُونَ وَالآخِرُونَ، يَا حَيّاً قَبْلَ كُلِّ حَيٍّ، وَيَا حَيّاً بَعْدَ كُلِّ حَيٍّ، وَيَا حَيّاً حِينَ لا حَيَّ، يَا مُحْيِيَ الْمَوْتَى وَمُمِيتَ الأَحْيَاءِ، يَا حَيُّ لا إِلَهَ إِلا أَنْتَ.',
        'اللَّهُمَّ بَلِّغْ مَوْلانَا الإِمَامَ الْهَادِيَ الْمَهْدِيَّ الْقَائِمَ بِأَمْرِكَ، صَلَوَاتُ اللَّهِ عَلَيْهِ وَعَلَى آبَائِهِ الطَّاهِرِينَ، عَنْ جَمِيعِ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، فِي مَشَارِقِ الأَرْضِ وَمَغَارِبِهَا، سَهْلِهَا وَجَبَلِهَا، وَبَرِّهَا وَبَحْرِهَا، وَعَنِّي وَعَنْ وَالِدَيَّ مِنَ الصَّلَوَاتِ زِنَةَ عَرْشِ اللَّهِ وَمِدَادَ كَلِمَاتِهِ.',
        'اللَّهُمَّ إِنِّي أُجَدِّدُ لَهُ فِي صَبِيحَةِ يَوْمِي هَذَا، وَمَا عِشْتُ مِنْ أَيَّامِي، عَهْداً وَعَقْداً وَبَيْعَةً لَهُ فِي عُنُقِي، لا أَحُولُ عَنْهَا وَلا أَزُولُ أَبَداً. اللَّهُمَّ اجْعَلْنِي مِنْ أَنْصَارِهِ وَأَعْوَانِهِ، وَالذَّابِّينَ عَنْهُ، وَالْمُسَارِعِينَ إِلَيْهِ فِي قَضَاءِ حَوَائِجِهِ، وَالْمُمْتَثِلِينَ لأَوَامِرِهِ، وَالْمُحَامِينَ عَنْهُ، وَالسَّابِقِينَ إِلَى إِرَادَتِهِ، وَالْمُسْتَشْهَدِينَ بَيْنَ يَدَيْهِ.',
      ],
    ),

    // 13. المناجاة الشعبانية
    AhlulbaytDua(
      id: 'munajat_shabaniyah',
      title: 'المناجاة الشعبانية',
      attributedTo: 'أمير المؤمنين والأئمة الأطهار (عليهم السلام)',
      category: 'المناجاة والخشوع المطلق',
      summary:
          'مناجاة شريفة عظيمة كان يدعو بها أمير المؤمنين والأئمة الأطهار في شهر شعبان؛ وفيها غاية التذلل والإنابة والتعلق برحمة الله ومغفرته.',
      paragraphs: [
        'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَاسْمَعْ دُعَائِي إِذَا دَعَوْتُكَ، وَاسْمَعْ نِدَائِي إِذَا نَادَيْتُكَ، وَأَقْبِلْ عَلَيَّ إِذَا نَاجَيْتُكَ، فَقَدْ هَرَبْتُ إِلَيْكَ، وَوَقَفْتُ بَيْنَ يَدَيْكَ مُسْتَكِيناً لَكَ، مُتَضَرِّعاً إِلَيْكَ، رَاجِياً لِمَا لَدَيْكَ ثَوَابِي، وَتَعْلَمُ مَا فِي نَفْسِي، وَتَخْبُرُ حَاجَتِي، وَتَعْرِفُ ضَمِيرِي، وَلا يَخْفَى عَلَيْكَ أَمْرُ مُنْقَلَبِي وَمَثْوَايَ.',
        'إِلَهِي إِنْ حَرَمْتَنِي فَمَنْ ذَا الَّذِي يَرْزُقُنِي؟ وَإِنْ خَذَلْتَنِي فَمَنْ ذَا الَّذِي يَنْصُرُنِي؟ إِلَهِي أَعُوذُ بِكَ مِنْ غَضَبِكَ وَحُلُولِ سَخَطِكَ. إِلَهِي إِنْ كُنْتُ غَيْرَ مُسْتَأْهِلٍ لِرَحْمَتِكَ فَأَنْتَ أَهْلٌ أَنْ تَجُودَ عَلَيَّ بِفَضْلِ سَعَتِكَ.',
        'إِلَهِي كَأَنِّي بِنَفْسِي وَاقِفَةٌ بَيْنَ يَدَيْكَ وَقَدْ أَظَلَّهَا حُسْنُ تَوَكُّلِي عَلَيْكَ، فَقُلْتَ مَا أَنْتَ أَهْلُهُ، وَتَغَمَّدْتَنِي بِعَفْوِكَ. إِلَهِي إِنْ عَفَوْتَ فَمَنْ أَوْلَى مِنْكَ بِذَلِكَ؟ وَإِنْ كَانَ قَدْ دَنَا أَجَلِي وَلَمْ يُدْنِنِي مِنْكَ عَمَلِي، فَقَدْ جَعَلْتُ الإِقْرَارَ بِالذَّنْبِ إِلَيْكَ وَسِيلَتِي.',
        'إِلَهِي هَبْ لِي كَمَالَ الانْقِطَاعِ إِلَيْكَ، وَأَنِرْ أَبْصَارَ قُلُوبِنَا بِضِيَاءِ نَظَرِهَا إِلَيْكَ، حَتَّى تَخْرِقَ أَبْصَارُ الْقُلُوبِ حُجُبَ النُّورِ فَتَصِلَ إِلَى مَعْدِنِ الْعَظَمَةِ، وَتَصِيرَ أَرْوَاحُنَا مُعَلَّقَةً بِعِزِّ قُدْسِكَ.',
      ],
    ),

    // 14. دعاء يستشير
    AhlulbaytDua(
      id: 'dua_yastasheer',
      title: 'دعاء يستشير',
      attributedTo: 'أمير المؤمنين علي بن أبي طالب (عليه السلام)',
      category: 'تمجيد الله ورفع الشدائد',
      summary:
          'علّمه رسول الله ﷺ لأمير المؤمنين؛ فيه الثناء على الله بصفاته العليا وعظمته وقدرته على كل شيء، ويُقرأ في كل صباح ومساء وعند الشدائد.',
      paragraphs: [
        'الْحَمْدُ لِلَّهِ الَّذِي لا إِلَهَ إِلا هُوَ الْمَلِكُ الْحَقُّ الْمُبِينُ، الْمُدَبِّرُ بِلا وَزِيرٍ، وَلا خَلْقٍ مِنْ عِبَادِهِ يَسْتَشِيرُ، الأَوَّلُ غَيْرُ مَوْصُوفٍ، وَالْبَاقِي بَعْدَ فَنَاءِ الْخَلْقِ، الْعَظِيمُ الرُّبُوبِيَّةِ، نُورُ السَّمَاوَاتِ وَالأَرَضِينَ وَفَاطِرُهُمَا وَمُبْتَدِعُهُمَا، بِغَيْرِ عَمَدٍ خَلَقَهُمَا، وَفَتَقَهُمَا فَتْقاً، فَقَامَتِ السَّمَاوَاتُ طَائِعَاتٍ بِأَمْرِهِ، وَاسْتَقَرَّتِ الأَرَضُونَ بِأَوْتَادِهَا فَوْقَ الْمَاءِ.',
        'ثُمَّ عَلا رَبُّنَا فِي السَّمَاوَاتِ الْعُلا، الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى، لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ الثَّرَى. فَأَنَا أَشْهَدُ بِأَنَّكَ أَنْتَ اللَّهُ لا رَافِعَ لِمَا وَضَعْتَ، وَلا وَاضِعَ لِمَا رَفَعْتَ، وَلا مُعِزَّ لِمَنْ أَذْلَلْتَ، وَلا مُذِلَّ لِمَنْ أَعْزَزْتَ، وَلا مَانِعَ لِمَا أَعْطَيْتَ، وَلا مُعْطِيَ لِمَا مَنَعْتَ.',
        'وَأَنْتَ اللَّهُ لا إِلَهَ إِلا أَنْتَ، كُنْتَ إِذْ لَمْ تَكُنْ سَمَاءٌ مَبْنِيَّةٌ، وَلا أَرْضٌ مَدْحِيَّةٌ، وَلا شَمْسٌ مُضِيئَةٌ، وَلا لَيْلٌ مُظْلِمٌ، وَلا نَهَارٌ مُضِيءٌ، وَلا بَحْرٌ لُجِّيٌّ، وَلا جَبَلٌ رَاسٍ، وَلا نَجْمٌ سَارٍ، وَلا قَمَرٌ مُنِيرٌ، وَلا رِيحٌ تَهُبُّ، وَلا سَحَابٌ يَسْكُبُ، وَلا بَرْقٌ يَلْمَعُ، وَلا رَعْدٌ يُسَبِّحُ، وَلا رُوحٌ تَتَنَفَّسُ، وَلا طَائِرٌ يَطِيرُ، وَلا نَارٌ تَتَوَقَّدُ، وَلا مَاءٌ يَطَّرِدُ، كُنْتَ قَبْلَ كُلِّ شَيْءٍ، وَكَوَّنْتَ كُلَّ شَيْءٍ، وَقَدَرْتَ عَلَى كُلِّ شَيْءٍ، وَابْتَدَعْتَ كُلَّ شَيْءٍ، وَأَغْنَيْتَ وَأَفْقَرْتَ، وَأَمَتَّ وَأَحْيَيْتَ، وَأَفْرَحْتَ وَأَبْكَيْتَ، سُبْحَانَكَ وَتَعَالَيْتَ.',
      ],
    ),
  ];

  /// جميع الأدعية المتاحة.
  List<AhlulbaytDua> getAllDuas() => defaultDuas;

  /// جلب دعاء بواسطة المعرف.
  AhlulbaytDua? getDuaById(String id) {
    try {
      return defaultDuas.firstWhere((d) => d.id == id);
    } catch (_) {
      return null;
    }
  }

  /// البحث في الأدعية بالعنوان أو النص أو المنسوب إليه.
  List<AhlulbaytDua> searchDuas(String query) {
    if (query.trim().isEmpty) return defaultDuas;
    final q = query.trim();
    return defaultDuas.where((d) {
      return d.title.contains(q) ||
          d.attributedTo.contains(q) ||
          d.summary.contains(q) ||
          d.fullText.contains(q);
    }).toList();
  }
}
